<?php
require_once __DIR__.'/../includes/bootstrap.php';
$user=require_login('traveler');
$stmt=db()->prepare('SELECT b.id,b.booking_number,b.total_amount,b.currency,b.payment_status,b.booking_status,b.created_at,p.business_name,tr.destination,tr.start_date,tr.end_date FROM bookings b INNER JOIN providers p ON p.id=b.provider_id LEFT JOIN trip_requests tr ON tr.id=b.trip_request_id WHERE b.user_id=? ORDER BY b.created_at DESC');$stmt->bind_param('i',$user['id']);$stmt->execute();$bookings=$stmt->get_result();
$page_title='My Bookings';require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">My Bookings</h1><p class="text-secondary mb-0">Bookings created from accepted provider offers.</p></div><a href="/account/dashboard.php" class="btn btn-outline-dark">Dashboard</a></div><div class="card"><div class="card-body"><?php if($bookings->num_rows===0):?><p class="text-secondary mb-0">No bookings yet.</p><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Booking</th><th>Provider</th><th>Trip</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><?php while($b=$bookings->fetch_assoc()):?><tr><td><?=e($b['booking_number'])?></td><td><?=e($b['business_name'])?></td><td><?=e($b['destination']??'')?><?php if($b['start_date']):?><div class="small text-secondary"><?=e($b['start_date'])?> → <?=e($b['end_date'])?></div><?php endif;?></td><td><?=e($b['currency'])?> <?=number_format((float)$b['total_amount'],2)?></td><td><span class="badge text-bg-light"><?=e($b['booking_status'])?></span><div class="small text-secondary">Payment: <?=e($b['payment_status'])?></div></td><td><a href="/account/booking-view.php?id=<?=$b['id']?>">View</a></td></tr><?php endwhile;?></tbody></table></div><?php endif;?></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
